begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000001','validation@example.test');
insert into organizations(id,name) values('10000000-0000-0000-0000-000000000001','LP3H Fiktif');
insert into memberships(organization_id,user_id,role) values('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','companion');
insert into business_contacts(id,organization_id,owner_id,business_name,whatsapp_number) values('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','Usaha Fiktif','6281200000101');
insert into cases(id,organization_id,contact_id,assignee_id) values('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001');
insert into revision_tasks(id,case_id,instruction) values('40000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','Instruksi fiktif');
select throws_ok($$insert into revision_tasks(case_id,instruction) values('30000000-0000-0000-0000-000000000001',E'\t\n')$$,'23514',null,'table rejects tab/newline-only instruction');
select throws_ok($$insert into organizations(name) values(E'\t\n')$$,'23514',null,'table rejects whitespace-only organization name');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select throws_ok($$select create_task('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000001',E'\t\n',null)$$,'22023',null,'create RPC rejects tab/newline-only instruction');
select throws_ok($$select update_task('50000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001',1,E'\t\n','needs_sending',null,false)$$,'22023',null,'update RPC rejects tab/newline-only instruction');
select throws_ok($$select create_task('50000000-0000-0000-0000-000000000003','40000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000001',chr(160)||chr(65279),null)$$,'22023',null,'RPC trim matches Unicode whitespace handled by the frontend');
select throws_ok($$select create_contact('50000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001',E'\t\n','6281200000102','',false)$$,'22023',null,'contact RPC rejects whitespace-only business name');
select is((select instruction from revision_tasks where id='40000000-0000-0000-0000-000000000001'),'Instruksi fiktif','failed whitespace edit retains original instruction');
reset role;
select * from finish();
rollback;
